package ultra.downloads;
import android.app.*;import android.content.*;import android.view.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowAlertDialog;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28)
public class DL27CopiesTest {
 Context c;
 @Before public void setup(){c=Robolectric.buildActivity(Activity.class).setup().get();c.setTheme(android.R.style.Theme_Material_NoActionBar);app.revanced.extension.shared.utils.Utils.testContext=c;Art.network=false;Library.prefs(c).edit().clear().commit();PlaylistIndex.invalidateCache();}
 Catalog.Track t(String id){return new Catalog.Track(id,"Song "+id,"Artist","Album");}
 void seed(String id,String name,String...ids)throws Exception{PlaylistIndex.register("VL"+id,name);List<Catalog.Track> ts=new ArrayList<>();for(String x:ids)ts.add(t(x));PlaylistIndex.record(id,ts,true);}
 int tagged(View v,String tag){int n=tag.equals(v.getTag())?1:0;if(v instanceof ViewGroup)for(int k=0;k<((ViewGroup)v).getChildCount();k++)n+=tagged(((ViewGroup)v).getChildAt(k),tag);return n;}
 @Test public void existingRosterIsVisibleToDeviceSongsWithoutCreatingEmptyManualPlaylist()throws Exception{seed("PLone","Synthetic mix A","aaaaaaaaaaa");seed("PLtwo","Synthetic mix B","bbbbbbbbbbb");PlaylistPicker.show(c,Arrays.asList(t("localfile")),()->{});View root=ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView();assertEquals(2,tagged(root,"local_destination"));assertEquals(0,tagged(root,"account_destination"));assertEquals(0,tagged(root,"local_empty_state"));assertEquals(2,PlaylistIndex.groups(c).size()-1);}
 @Test public void localAdditionNeverChangesSourceAndSurvivesRefresh()throws Exception{seed("PLone","List","aaaaaaaaaaa");String remote=Library.prefs(c).getString("local_playlist_index","");assertEquals(1,LocalPlaylistCopies.add(c,"PLone",Arrays.asList(t("bbbbbbbbbbb"))));assertEquals(remote,Library.prefs(c).getString("local_playlist_index",""));PlaylistIndex.record("PLone",Arrays.asList(t("ccccccccccc")),true);assertEquals(new HashSet<>(Arrays.asList("aaaaaaaaaaa","bbbbbbbbbbb")),PlaylistIndex.members(c,"PLone"));assertEquals(1,PlaylistIndex.read(c).getJSONObject("PLone").getJSONArray("tracks").length());}
 @Test public void localRemovalDoesNotDeleteAudioOrSourceAndDoesNotComeBack()throws Exception{seed("PLone","List","aaaaaaaaaaa","bbbbbbbbbbb");String remote=Library.prefs(c).getString("local_playlist_index","");assertEquals(1,LocalPlaylistCopies.remove(c,"PLone",Collections.singleton("aaaaaaaaaaa")));assertEquals(remote,Library.prefs(c).getString("local_playlist_index",""));assertEquals(Collections.singleton("bbbbbbbbbbb"),PlaylistIndex.members(c,"PLone"));PlaylistIndex.record("PLone",Arrays.asList(t("aaaaaaaaaaa"),t("bbbbbbbbbbb")),true);assertEquals(Collections.singleton("bbbbbbbbbbb"),PlaylistIndex.members(c,"PLone"));}
 @Test public void sameNamesKeepDistinctSourceIdsAndManualPlaylist()throws Exception{seed("PLone","Mix","aaaaaaaaaaa");seed("PLtwo","Mix","bbbbbbbbbbb");PlaylistPicker.add(c,"Mix",Arrays.asList(t("ccccccccccc")));LocalPlaylistCopies.add(c,"PLone",Arrays.asList(t("ddddddddddd")));assertEquals(2,PlaylistIndex.total(c,"PLone"));assertEquals(1,PlaylistIndex.total(c,"PLtwo"));assertEquals(1,PlaylistIndex.total(c,"local:Mix"));assertEquals(4,PlaylistIndex.groups(c).size());}
 @Test public void partialCopyLoadsMoreUntilEditedThenStaysIndependent()throws Exception{PlaylistIndex.register("VLPLone","List");PlaylistIndex.record("PLone",Arrays.asList(t("aaaaaaaaaaa")),false);assertEquals(1,PlaylistIndex.total(c,"PLone"));PlaylistIndex.record("PLone",Arrays.asList(t("aaaaaaaaaaa"),t("bbbbbbbbbbb")),false);assertEquals(2,PlaylistIndex.total(c,"PLone"));LocalPlaylistCopies.add(c,"PLone",Arrays.asList(t("ccccccccccc")));PlaylistIndex.record("PLone",Arrays.asList(t("ddddddddddd")),true);assertEquals(3,PlaylistIndex.total(c,"PLone"));assertTrue(PlaylistIndex.complete(c,"PLone"));}
 @Test public void completedCopyDoesNotFollowLaterOnlineEdits()throws Exception{seed("PLone","List","aaaaaaaaaaa");assertEquals(1,PlaylistIndex.total(c,"PLone"));PlaylistIndex.record("PLone",Arrays.asList(t("bbbbbbbbbbb")),true);assertEquals(Collections.singleton("aaaaaaaaaaa"),PlaylistIndex.members(c,"PLone"));}
 @Test public void copySurvivesNewEmptyOnlineRosterAndCacheReset()throws Exception{seed("PLone","List","aaaaaaaaaaa");assertTrue(PlaylistIndex.groups(c).containsKey("PLone"));String copy=Library.prefs(c).getString(LocalPlaylistCopies.PREF,"");PlaylistIndex.roster(c,Collections.emptyList());PlaylistIndex.invalidateCache();assertEquals(copy,Library.prefs(c).getString(LocalPlaylistCopies.PREF,""));assertTrue(PlaylistIndex.groups(c).containsKey("PLone"));assertEquals(1,PlaylistIndex.total(c,"PLone"));}
 @Test public void duplicateAddsSkipExistingAndKeepOriginalOrder()throws Exception{seed("PLone","List","aaaaaaaaaaa");assertEquals(1,LocalPlaylistCopies.add(c,"PLone",Arrays.asList(t("aaaaaaaaaaa"),t("bbbbbbbbbbb"),t("bbbbbbbbbbb"))));JSONArray a=LocalPlaylistCopies.entry(c,"PLone").getJSONArray("tracks");assertEquals("aaaaaaaaaaa",a.getJSONObject(0).getString("id"));assertEquals("bbbbbbbbbbb",a.getJSONObject(1).getString("id"));}
 @Test public void allLocalChangesPersistAcrossCacheInvalidation()throws Exception{seed("PLone","List","aaaaaaaaaaa");LocalPlaylistCopies.add(c,"PLone",Arrays.asList(t("bbbbbbbbbbb")));PlaylistIndex.invalidateCache();assertEquals(2,PlaylistIndex.total(c,"PLone"));assertTrue(new JSONObject(Library.prefs(c).getString(LocalPlaylistCopies.PREF,"{}")).getJSONObject("PLone").getBoolean("edited"));}
 @Test public void onlineWriteEntryPointFailsBeforeAnyRequest()throws Exception{try{AccountPlaylists.add(c,"PLone",Arrays.asList(t("aaaaaaaaaaa")));fail();}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("disabled"));}}
 @Test public void missingTracksStayExplicitAndDeviceAudioCanJoinCopy()throws Exception{seed("PLone","List","aaaaaaaaaaa");LocalPlaylistCopies.add(c,"PLone",Arrays.asList(t("localAudio1")));List<Library.Item> rows=PlaylistIndex.ordered(c,"PLone",Collections.emptyList(),true);assertEquals(2,rows.size());assertEquals("unavailable",rows.get(0).state);assertEquals("localAudio1",rows.get(1).id);}
 @Test public void likedPlaylistAliasesRemainOneLocalCopy()throws Exception{seed("LM","Liked music","aaaaaaaaaaa");seed("PLlikedAlias","Liked Songs","bbbbbbbbbbb");assertEquals(2,PlaylistIndex.groups(c).size());assertEquals(2,PlaylistIndex.total(c,"LM"));LocalPlaylistCopies.add(c,"LM",Arrays.asList(t("ccccccccccc")));assertEquals(3,PlaylistIndex.total(c,"LM"));}
}
